import{_ as n,o as i,c as e,a2 as u}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Hukum Jaminan Perumahan","description":"","frontmatter":{},"headers":[],"relativePath":"id/0045-住房保障法.md","filePath":"id/0045-住房保障法.md"}'),t={name:"id/0045-住房保障法.md"};function r(s,a,m,d,k,l){return i(),e("div",null,[...a[0]||(a[0]=[u('<h1 id="hukum-jaminan-perumahan" tabindex="-1">Hukum Jaminan Perumahan <a class="header-anchor" href="#hukum-jaminan-perumahan" aria-label="Permalink to &quot;Hukum Jaminan Perumahan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>45</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Hak Hunian, Perumahan Jaminan, Yurisdiksi Ruang, Lingkungan Layak Huni, Anti-Spekulasi</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Jaminan Perumahan》 adalah salah satu dari lima hukum pendukung peradaban simbiosis jangkar, bertujuan untuk menjamin hak hunian semua makhluk di dalam Hengyuanzhou, membangun sistem jaminan perumahan yang adil dan berkelanjutan, memanfaatkan teknologi yurisdiksi ruang untuk menyediakan ruang hunian yang layak bagi semua ras, dan mencegah spekulasi serta perampokan di bidang perumahan.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Jaminan Hunian</td><td>Setiap makhluk berhak mendapatkan ruang hunian yang layak, negara dan peradaban memiliki kewajiban untuk menjamin kebutuhan hunian dasar</td></tr><tr><td>Prinsip Prioritas Kesejahteraan Umum</td><td>Perumahan pada dasarnya adalah kebutuhan hidup pokok, bukan barang spekulasi, perumahan jaminan memiliki sifat kesejahteraan umum</td></tr><tr><td>Prinsip Efisiensi Ruang</td><td>Memanfaatkan teknologi yurisdiksi ruang untuk meningkatkan efisiensi pemanfaatan ruang dan memperluas ruang yang layak huni</td></tr><tr><td>Prinsip Adaptasi Antar Ras</td><td>Menyediakan ruang hunian yang adaptif terhadap karakteristik fisiologis dan kebiasaan hidup ras yang berbeda</td></tr><tr><td>Prinsip Lingkungan Layak Huni</td><td>Ruang hunian harus memiliki lingkungan ekologis yang baik, infrastruktur dasar, dan layanan publik</td></tr><tr><td>Prinsip Anti-Spekulasi</td><td>Melarang spekulasi dengan perumahan sebagai objek, mencegah perumahan menjadi alat perampokan kekayaan</td></tr></tbody></table><h2 id="ii-jaminan-hukum-hak-hunian" tabindex="-1">II. Jaminan Hukum Hak Hunian <a class="header-anchor" href="#ii-jaminan-hukum-hak-hunian" aria-label="Permalink to &quot;II. Jaminan Hukum Hak Hunian&quot;">​</a></h2><p>Hukum ini menetapkan dengan jelas bahwa hak hunian adalah hak dasar yang diberikan kepada setiap makhluk oleh Konstitusi Simbiosis, termasuk secara spesifik:</p><ol><li><strong>Hak Hunian Dasar</strong>: Setiap makhluk berhak mendapatkan ruang hunian tidak kurang dari standar minimum, dan standar minimum ditentukan sesuai dengan ukuran tubuh dan kebutuhan hidup ras.</li><li><strong>Hak Pengajuan Perumahan Jaminan</strong>: Makhluk yang memenuhi syarat berhak mengajukan perumahan jaminan, dan syarat pengajuan serta kriteria distribusi terbuka dan transparan.</li><li><strong>Hak Keamanan Hunian</strong>: Ruang hunian harus memenuhi standar keamanan, dan rumah berbahaya serta ruang yang tidak layak huni tidak boleh disewakan atau didistribusikan.</li><li><strong>Hak Stabilitas Hunian</strong>: Penghuni perumahan jaminan, jika memenuhi syarat, menikmati hak hunian yang stabil dan tidak boleh diusir secara sewenang-wenang.</li><li><strong>Hak Lingkungan Hunian</strong>: Penghuni berhak mendapatkan udara bersih, sumber air, dan lingkungan sekitar yang baik, serta berhak mengajukan keluhan tentang pencemaran lingkungan.</li><li><strong>Hak Renovasi Hunian</strong>: Penghuni berhak melakukan renovasi yang wajar pada ruang hunian, asalkan tidak memengaruhi keamanan bangunan dan hak pihak lain.</li></ol><h2 id="iii-sistem-jaminan-perumahan" tabindex="-1">III. Sistem Jaminan Perumahan <a class="header-anchor" href="#iii-sistem-jaminan-perumahan" aria-label="Permalink to &quot;III. Sistem Jaminan Perumahan&quot;">​</a></h2><p>Sistem jaminan perumahan peradaban simbiosis jangkar dibagi menjadi tiga jenis perumahan, mencakup berbagai tingkat kebutuhan:</p><table tabindex="0"><thead><tr><th>Jenis</th><th>Nama</th><th>Objek Jaminan</th><th>Metode Distribusi</th><th>Sewa/Harga</th></tr></thead><tbody><tr><td>Jenis pertama</td><td>Perumahan Sewa Publik</td><td>Kelompok berpenghasilan rendah, kultivator pemula, imigran baru</td><td>Sistem pengajuan dan peninjauan, distribusi antrean</td><td>Sewa rendah simbolis</td></tr><tr><td>Jenis kedua</td><td>Perumahan Hak Milik Bersama</td><td>Kelompok berpenghasilan menengah, kultivator tingkat menengah</td><td>Sistem pengajuan dan peninjauan, distribusi undian</td><td>Di bawah harga pasar, hak milik bersama antara individu dan negara</td></tr><tr><td>Jenis ketiga</td><td>Perumahan Komersial</td><td>Kelompok berpenghasilan tinggi, kultivator tingkat lanjut</td><td>Transaksi pasar</td><td>Harga pasar, tunduk pada pengaturan</td></tr></tbody></table><p>Selain itu, teknologi lipat ruang digunakan untuk membangun &quot;Area Perumahan Ruang Lipat&quot;: di dalam ruang fisik yang terbatas, teknologi lipat ruang memperluas area hunian, menyediakan lebih banyak ruang hunian untuk area padat penduduk. Area perumahan ruang lipat harus melalui evaluasi keamanan untuk memastikan stabilitas ruang.</p><h2 id="iv-adaptasi-perumahan-antar-ras" tabindex="-1">IV. Adaptasi Perumahan Antar Ras <a class="header-anchor" href="#iv-adaptasi-perumahan-antar-ras" aria-label="Permalink to &quot;IV. Adaptasi Perumahan Antar Ras&quot;">​</a></h2><p>Untuk kebutuhan hunian khusus dari ras yang berbeda di dalam Hengyuanzhou, hukum ini menetapkan sistem adaptasi perumahan antar ras:</p><ul><li><strong>Ras Akuatik</strong>: Menyediakan ruang hunian bawah air atau hunian amfibi air-darat, dilengkapi dengan sistem sirkulasi air dan pemeliharaan kualitas air.</li><li><strong>Ras Terbang</strong>: Menyediakan ruang hunian di ketinggian atau hunian dengan platform lepas landas dan mendarat, dilengkapi dengan manajemen lalu lintas udara.</li><li><strong>Kehidupan Energi</strong>: Menyediakan ruang hunian dengan konsentrasi energi yang sesuai, dilengkapi dengan perangkat stabilisasi energi.</li><li><strong>Ras Raksasa</strong>: Menyediakan ruang hunian skala besar, dengan struktur bangunan yang diperkuat secara khusus.</li><li><strong>Ras Mikroskopis</strong>: Menyediakan area perumahan mikroskopis, dilengkapi dengan saluran skala dan fasilitas khusus.</li></ul><p>Standar adaptasi perumahan antar ras dirumuskan bersama oleh departemen perumahan yang berwenang dan perwakilan setiap ras, dan diperbarui secara berkala.</p><h2 id="v-pembangunan-dan-pengelolaan-perumahan" tabindex="-1">V. Pembangunan dan Pengelolaan Perumahan <a class="header-anchor" href="#v-pembangunan-dan-pengelolaan-perumahan" aria-label="Permalink to &quot;V. Pembangunan dan Pengelolaan Perumahan&quot;">​</a></h2><ul><li><strong>Perencanaan Pembangunan Perumahan</strong>: Negara merumuskan perencanaan pembangunan perumahan sesuai dengan pertumbuhan penduduk dan situasi imigrasi, memastikan keseimbangan antara pasokan dan permintaan perumahan.</li><li><strong>Standar Pembangunan</strong>: Pembangunan perumahan jaminan harus memenuhi standar keamanan, lingkungan, dan layak huni, dan dilarang menurunkan kualitas pembangunan.</li><li><strong>Pengelolaan Properti</strong>: Area perumahan mengadopsi model yang menggabungkan pengelolaan mandiri dan pengelolaan properti profesional, dan penghuni berhak berpartisipasi dalam keputusan pengelolaan properti.</li><li><strong>Perawatan Perumahan</strong>: Perawatan perumahan jaminan menjadi tanggung jawab lembaga pengelola perumahan, dan dana perawatan ditanggung dari akumulasi publik.</li><li><strong>Mekanisme Keluar</strong>: Ketika pendapatan atau tingkat kultivasi penghuni perumahan jaminan melebihi standar jaminan, mereka harus keluar dari perumahan jaminan atau mengubahnya menjadi perumahan komersial, dan diberikan masa transisi yang wajar.</li></ul><h2 id="vi-anti-spekulasi-dan-pengawasan" tabindex="-1">VI. Anti-Spekulasi dan Pengawasan <a class="header-anchor" href="#vi-anti-spekulasi-dan-pengawasan" aria-label="Permalink to &quot;VI. Anti-Spekulasi dan Pengawasan&quot;">​</a></h2><p>Untuk mencegah spekulasi dan perampokan di bidang perumahan, hukum ini menetapkan langkah-langkah pengawasan berikut:</p><ol><li>Membatasi jumlah perumahan komersial yang dapat dimiliki individu, dan mengenakan pajak properti progresif atas kelebihannya.</li><li>Melarang subsewa dan penjualan kembali perumahan jaminan, dan pelanggar akan dicabut kualifikasi jaminannya dan perumahannya diambil kembali.</li><li>Membangun sistem keterbukaan informasi transaksi perumahan, untuk mencegah operasi kotak hitam dan manipulasi harga.</li><li>Menerapkan manajemen kualifikasi dan pengawasan dana bagi pengembang real estat, untuk mencegah pembangunan tidak selesai dan penipuan.</li><li>Membangun mekanisme keluhan perumahan dan penyelesaian sengketa, untuk menjamin hak hukum penghuni.</li></ol><h2 id="vii-tanggung-jawab-hukum" tabindex="-1">VII. Tanggung Jawab Hukum <a class="header-anchor" href="#vii-tanggung-jawab-hukum" aria-label="Permalink to &quot;VII. Tanggung Jawab Hukum&quot;">​</a></h2><p>Kegiatan yang melanggar ketentuan hukum ini menanggung tanggung jawab berikut sesuai tingkat keparahan pelanggaran:</p><ul><li>Mendistribusikan perumahan jaminan secara melanggar aturan, diperintahkan memperbaiki dan menghukum orang yang bertanggung jawab.</li><li>Menyewakan ulang atau menjual kembali perumahan jaminan, mencabut kualifikasi jaminan, mengambil kembali perumahan, dan mendenda.</li><li>Pengembang menurunkan kualitas pembangunan, diperintahkan membangun kembali dan didenda, dalam kasus parah kualifikasi dicabut.</li><li>Spekulasi perumahan, mengenakan pajak spekulasi tinggi dan mendenda.</li><li>Menyewakan rumah berbahaya yang menyebabkan kerusakan pada penghuni, menanggung tanggung jawab ganti rugi, dalam kasus parah dituntut tanggung jawab pidana.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Jaminan Perumahan》 adalah implementasi dari konsep &quot;setiap orang memiliki jalan&quot; peradaban simbiosis jangkar di bidang hunian. Dengan membangun sistem jaminan perumahan yang terklasifikasi, memanfaatkan teknologi yurisdiksi ruang untuk memperluas ruang hunian, mengadaptasi kebutuhan hunian antar ras, dan memberantas spekulasi perumahan, ia memastikan setiap makhluk dapat memiliki rumah yang aman, layak, dan stabil, serta menyediakan jaminan hunian untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>39-住房与环境保障 (Jaminan Perumahan dan Lingkungan)</li><li>13-空间法理调度体系详解 (Penjelasan Rinci Sistem Yurisdiksi Ruang)</li><li>46-环境保护法 (Hukum Perlindungan Lingkungan)</li></ul>',29)])])}const p=n(t,[["render",r]]);export{h as __pageData,p as default};
